// And groups predicates with the AND operator between them.
func And(predicates ...predicate.GiftTransaction) predicate.GiftTransaction {
	return predicate.GiftTransaction(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.GiftTransaction) predicate.GiftTransaction {
	return predicate.GiftTransaction(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.GiftTransaction) predicate.GiftTransaction {
	return predicate.GiftTransaction(sql.NotPredicates(p))
}
